import {
  Box,
  Typography,
  Container,
} from "@mui/material";


export default function Footer() {

  return (
<Box
  sx={{
    mt: 10,
    py: 6,
    px: 4,
    background:
      "linear-gradient(to right, #020617, #0f172a, #1e293b)",
    color: "white",
  }}
>

  {/* TOP SECTION */}

  <Box
    sx={{
      display: "flex",
      alignItems: "center",
      gap: 2,
      mb: 3,
    }}
  >

    <img
      src="/logo.png"
      alt="logo"
      width="50"
    />

    <Typography
      variant="h3"
      fontWeight={800}
    >
      DevBlog
    </Typography>

  </Box>

  {/* DESCRIPTION */}

  <Typography
    variant="body1"
    sx={{
      opacity: 0.75,
      maxWidth: "500px",
      lineHeight: 2,
      mb: 4,
      fontSize: "1.05rem",
    }}
  >
    A modern blogging platform built
    using MERN Stack and Material UI.
  </Typography>

  {/* DIVIDER */}

  <Box
    sx={{
      height: "1px",
      background:
        "rgba(255,255,255,0.1)",
      mb: 4,
    }}
  />

  {/* BOTTOM */}

  <Box
    sx={{
      display: "flex",
      justifyContent:
        "space-between",
      alignItems: "center",
      flexWrap: "wrap",
      gap: 2,
    }}
  >

    <Typography
      sx={{ opacity: 0.7 }}
    >
      © 2026 DevBlog. All rights
      reserved.
    </Typography>

    <Typography
      sx={{ opacity: 0.7 }}
    >
      Built with ❤️ using MERN
    </Typography>

  </Box>

</Box>
  );
}
